// Add compute_marker column to all rows
const items = $input.all();

for (const item of items) {
  item.json.compute_marker = 1;
}

return items;

// Parse the AI response and prepare for Excel update
const aiResponse = $input.first().json;

let extractedData;
try {
  // Parse if it's a string
  if (typeof aiResponse.message?.content === 'string') {
    extractedData = JSON.parse(aiResponse.message.content);
  } else {
    extractedData = aiResponse.message?.content || aiResponse;
  }
} catch (e) {
  // Fallback regex extraction for investment amount
  const text = aiResponse.message?.content || JSON.stringify(aiResponse);
  const amountMatch = text.match(/[\$€£]?\s*([\d,]+\.?\d*)\s*(million|mn|m|billion|bn|b|thousand|k)?/i);

  let amount = 0;
  if (amountMatch) {
    amount = parseFloat(amountMatch[1].replace(/,/g, ''));
    const multiplier = amountMatch[2]?.toLowerCase();
    if (multiplier === 'million' || multiplier === 'mn' || multiplier === 'm') {
      amount *= 1000000;
    } else if (multiplier === 'billion' || multiplier === 'bn' || multiplier === 'b') {
      amount *= 1000000000;
    } else if (multiplier === 'thousand' || multiplier === 'k') {
      amount *= 1000;
    }
  }

  extractedData = {
    investment_amount: amount,
    currency: 'USD',
    extraction_method: 'regex_fallback'
  };
}

return [{
  json: {
    investment_amount: extractedData.investment_amount,
    currency: extractedData.currency || 'USD',
    investment_type: extractedData.investment_type || 'Unknown',
    company_name: extractedData.company_name || 'Unknown',
    confidence: extractedData.confidence || 0.5,
    extracted_at: new Date().toISOString(),
    source: 'IC_Memo_PDF'
  }
}];

// Merge PDF extracted investment amount into Excel data
const items = $input.all();
const investmentData = $('Parse AI Response').first().json;

// Get all Excel rows
const excelRows = items.map(item => item.json);

// Add investment amount column to each row
// Or add as a new row with the extracted data
const updatedRows = excelRows.map((row, index) => {
  return {
    ...row,
    pdf_investment_amount: investmentData.investment_amount,
    pdf_currency: investmentData.currency,
    pdf_company_name: investmentData.company_name,
    pdf_investment_type: investmentData.investment_type,
    pdf_extraction_confidence: investmentData.confidence,
    pdf_extracted_at: investmentData.extracted_at,
    compute_marker: 1
  };
});

// If no existing Excel rows, create a new row with the PDF data
if (updatedRows.length === 0) {
  updatedRows.push({
    investment_amount: investmentData.investment_amount,
    currency: investmentData.currency,
    company_name: investmentData.company_name,
    investment_type: investmentData.investment_type,
    extraction_confidence: investmentData.confidence,
    extracted_at: investmentData.extracted_at,
    source: 'IC_Memo_PDF',
    compute_marker: 1
  });
}

return updatedRows.map(row => ({ json: row }));
